// fakeChain is one canned metadata-source binding the test's ModuleSources
// fake resolves (the module-config half of the seam input; the gate half
// comes from the real prefs rows).
type fakeChain struct {
	pluginID      string
	priority      int
	configEnabled bool
}

// gateFor implements the inherit-then-override gate contract over the stored
// prefs (the cmd-side resolution the Deps.ModuleSources closure owns — here
// re-implemented WITHOUT an enrich import, which api must never carry, INV2):
// absent rows inherit the config flag, a module-scope row (LibraryID 0)
// applies to every library, a library's own row replaces it. A gate can only
// mute a config-enabled source.
func gateFor(prefs []store.MetadataSourcePref, libraryID int64, pluginID string, configEnabled bool) bool {
	gate, gated := false, false
	for _, p := range prefs {
		if p.PluginID != pluginID {
			continue
		}
		switch {
		case libraryID != 0 && p.LibraryID == libraryID:
			gate, gated = p.Enabled, true
		case p.LibraryID == 0:
			gate, gated = p.Enabled, true
		}
	}
	if !gated {
		return configEnabled
	}
	return configEnabled && gate
}

// fakeModuleSources builds a Deps.ModuleSources closure over the canned
// module chains and the REAL prefs table — the response under test therefore
// resolves through the same store rows an operator wrote.
func fakeModuleSources(st *store.Store, chains map[string][]fakeChain) func(context.Context, string, int64) ([]string, []int, []bool, error) {
	return func(_ context.Context, moduleID string, libraryID int64) ([]string, []int, []bool, error) {
		chain, ok := chains[moduleID]
		if !ok {
			return nil, nil, nil, fmt.Errorf("unknown module %s", moduleID)
		}
		scope := []int64(nil)
		if libraryID != 0 {
			scope = []int64{libraryID}
		}
		prefs, err := st.ListMetadataSourcePrefs(context.Background(), moduleID, scope)
		if err != nil {
			return nil, nil, nil, err
		}
		pids := make([]string, 0, len(chain))
		prs := make([]int, 0, len(chain))
		ens := make([]bool, 0, len(chain))
		for _, b := range chain {
			pids = append(pids, b.pluginID)
			prs = append(prs, b.priority)
			ens = append(ens, gateFor(prefs, libraryID, b.pluginID, b.configEnabled))
		}
		return pids, prs, ens, nil
	}
}

// sourcesFixture builds the aggregate test rig: a store carrying one
