// fetchAdminSources GETs the aggregate and decodes it (admin credential).
func fetchAdminSources(t *testing.T, h http.Handler, query string) sourceAdminResponse {
	t.Helper()
	resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/sources"+query, "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	var out sourceAdminResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		t.Fatalf("decode sourceAdminResponse: %v", err)
	}
	return out
}

// sourceByID indexes the decoded aggregate by plugin id, failing on a wrong
// row count or order (boot order is part of the contract).
func sourceByID(t *testing.T, got sourceAdminResponse, wantOrder []string) map[string]sourceAdminSource {
	t.Helper()
	if len(got.Sources) != len(wantOrder) {
		t.Fatalf("sources = %d rows, want %d", len(got.Sources), len(wantOrder))
	}
	byID := make(map[string]sourceAdminSource, len(got.Sources))
	for i, src := range got.Sources {
		if src.PluginID != wantOrder[i] {
			t.Fatalf("sources[%d] = %s, want %s (boot order)", i, src.PluginID, wantOrder[i])
		}
		byID[src.PluginID] = src
	}
	return byID
}

// TestAdminSources is the metadata-source-admin aggregate joint test (api
// side): GET /admin/sources assembles the boot-literal inventory, the
// Deps.Status health, capability chips, chain positions, and the effective
// gate resolution per module and per library. The gate resolution closures
// are fakes over the REAL prefs table (api imports no enrich, INV2); the
// resolution contract itself is covered by the store/enrich suites.
func TestAdminSources(t *testing.T) {
	t.Run("aggregate_reports_chain_gates_health_caps", func(t *testing.T) {
		h, _, libA, libB := sourcesFixture(t)
		got := fetchAdminSources(t, h, "")
		byID := sourceByID(t, got, []string{"serial-parser", "frame-grabber", "shikimori", "tv-parser"})

		sh := byID["shikimori"]
		if sh.Name != "Shikimori" || sh.Description != "External Shikimori metadata enrichment for serials." {
			t.Fatalf("shikimori identity = %q/%q, want the localized literals", sh.Name, sh.Description)
		}
		if sh.Health == nil || sh.Health.State != "serving" || sh.Health.Message != "ok" ||
			sh.Health.Restarts != 1 || sh.Health.CheckedAt != "2026-10-20T00:00:00Z" {
			t.Fatalf("shikimori health = %+v, want the serving snapshot", sh.Health)
		}
		if len(sh.Capabilities) != 1 || sh.Capabilities[0] != "metadata_source" {
			t.Fatalf("shikimori capabilities = %v, want [metadata_source]", sh.Capabilities)
		}
		if len(sh.Chains) != 1 || sh.Chains[0] != (sourceAdminChain{ModuleID: "serial", Position: 3}) {
			t.Fatalf("shikimori chains = %+v, want [{serial 3}]", sh.Chains)
		}
		if enabled, ok := sh.Effective.Modules["serial"]; !ok || enabled {
			t.Fatalf("shikimori module resolution = %v/%v, want disabled", enabled, ok)
		}
		if enabled, ok := sh.Effective.Libraries[fmt.Sprint(libA)]; !ok || enabled {
			t.Fatalf("shikimori libA resolution = %v/%v, want disabled (module row inherits)", enabled, ok)
		}
		if enabled, ok := sh.Effective.Libraries[fmt.Sprint(libB)]; !ok || !enabled {
			t.Fatalf("shikimori libB resolution = %v/%v, want enabled (library override)", enabled, ok)
		}

		sp := byID["serial-parser"]
		if len(sp.Chains) != 1 || sp.Chains[0] != (sourceAdminChain{ModuleID: "serial", Position: 1}) {
			t.Fatalf("serial-parser chains = %+v, want [{serial 1}]", sp.Chains)
		}
		if !sp.Effective.Modules["serial"] || !sp.Effective.Libraries[fmt.Sprint(libA)] ||
			!sp.Effective.Libraries[fmt.Sprint(libB)] {
			t.Fatalf("serial-parser effective = %+v, want enabled everywhere", sp.Effective)
		}
		if sp.Health != nil {
			t.Fatalf("serial-parser health = %+v, want none (not in the snapshot)", sp.Health)
		}
		if len(sp.Capabilities) != 0 {
			t.Fatalf("serial-parser capabilities = %v, want empty (never null)", sp.Capabilities)
		}

		tv := byID["tv-parser"]
		if len(tv.Chains) != 1 || tv.Chains[0] != (sourceAdminChain{ModuleID: "tv", Position: 1}) {
			t.Fatalf("tv-parser chains = %+v, want [{tv 1}]", tv.Chains)
		}
		if !tv.Effective.Modules["tv"] {
			t.Fatalf("tv-parser module resolution = %+v, want default-enabled", tv.Effective)
		}
		if got.Sources[1].Name != "" || got.Sources[1].Description != "" {
			t.Fatalf("frame-grabber identity = %q/%q, want empty (no literal)", got.Sources[1].Name, got.Sources[1].Description)
		}
	})

	t.Run("title_counts_on_demand", func(t *testing.T) {
		h, st, libA, libB := sourcesFixture(t)
		ctx := context.Background()
		seed := []func() error{
			// Series with an object-shaped shikimori title → counts.
			func() error {
				return st.PutSeries(ctx, store.Series{ModuleID: "serial", LibraryID: libA,
					RelativePath: "Cobra", Status: "active",
					Document: json.RawMessage(`{"sources":{"shikimori":{"title":{"russian":"Кобра","romaji":"Cobra"}}}}`)})
			},
			// Series whose shikimori namespace is title-less → no count.
			func() error {
				return st.PutSeries(ctx, store.Series{ModuleID: "serial", LibraryID: libA,
					RelativePath: "Empty", Status: "active",
					Document: json.RawMessage(`{"sources":{"shikimori":{"year":2020}}}`)})
			},
			// Item with a string shikimori title (attached extra) → counts.
			func() error {
				return st.PutItem(ctx, store.Item{ID: "itm_titled", ModuleID: "serial", LibraryID: libB,
					FileID: "f1", RelativePath: "Cobra/s01e01.mkv", MediaType: "video", Status: "ready",
					Document: json.RawMessage(`{"sources":{"shikimori":{"title":"Кобра"}}}`)})
			},
			// Item whose only titled namespace is NOT a loaded plugin → no count.
			func() error {
				return st.PutItem(ctx, store.Item{ID: "itm_unloaded", ModuleID: "serial", LibraryID: libB,
					FileID: "f2", RelativePath: "Cobra/s01e02.mkv", MediaType: "video", Status: "ready",
					Document: json.RawMessage(`{"sources":{"kinopoisk":{"title":"unloaded"}}}`)})
			},
		}
		for _, put := range seed {
			if err := put(); err != nil {
				t.Fatalf("seed row: %v", err)
			}
		}

		order := []string{"serial-parser", "frame-grabber", "shikimori", "tv-parser"}
		without := fetchAdminSources(t, h, "")
		if sourceByID(t, without, order)["shikimori"].TitleCounts != nil {
			t.Fatalf("shikimori title_counts present without the flag")
		}

		with := fetchAdminSources(t, h, "?title_counts=true")
		withByID := sourceByID(t, with, order)
		if sh := withByID["shikimori"]; sh.TitleCounts == nil || sh.TitleCounts.Items != 1 || sh.TitleCounts.Series != 1 {
			t.Fatalf("shikimori title_counts = %+v, want {items:1 series:1}", sh.TitleCounts)
		}
		if fg := withByID["frame-grabber"]; fg.TitleCounts == nil || fg.TitleCounts.Items != 0 || fg.TitleCounts.Series != 0 {
			t.Fatalf("frame-grabber title_counts = %+v, want zero counts", fg.TitleCounts)
		}
	})

	t.Run("bad_title_counts_param_is_400", func(t *testing.T) {
		h, _, _, _ := sourcesFixture(t)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/sources?title_counts=maybe", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})

	t.Run("nil_closures_return_503", func(t *testing.T) {
		st := openAPIStore(t)
		h := New(Deps{AdminToken: adminToken, Store: st})
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/sources", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusServiceUnavailable {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusServiceUnavailable)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unavailable" {
			t.Fatalf("error code = %q, want unavailable", eb.Error.Code)
		}
	})

	t.Run("client_role_is_forbidden", func(t *testing.T) {
		st := openAPIStore(t)
		h := gatingRouter(Deps{AdminToken: adminToken, Store: st}, RoleClient)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/sources", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusForbidden {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusForbidden)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "forbidden" {
			t.Fatalf("error code = %q, want forbidden (the admin-group role error)", eb.Error.Code)
		}
	})
}
